SHELL := /bin/bash
PYTHON := python3
PYTHONPATH := $(shell pwd)
PYTHON_PATH := $(shell which python3 2>/dev/null || echo "not_found")
# GITLAB_REGISTRY_URL := https://gitlab.nvidia.com/api/v4/projects/189250/packages/pypi
NV_PRIVATE_PYPI_URL := https://urm.nvidia.com/artifactory/api/pypi/sw-networking-ai-security-pypi-local
