setup-pyproject:
	@echo "Setting up pyproject.toml..."
	@echo "Detected Python version: $(PYTHON_VERSION)"
	@echo "Updating pyproject.toml with detected Python version..."
	@cp pyproject.toml pyproject.toml.backup
	@sed -i.tmp 's/target-version = .*/target-version = "py$(PYTHON_VERSION_SHORT)"/' pyproject.toml
	@sed -i.tmp 's/python_version = .*/python_version = "$(PYTHON_VERSION)"/' pyproject.toml
	@sed -i.tmp 's/requires-python = .*/requires-python = ">=$(PYTHON_VERSION)"/' pyproject.toml
	@rm -f pyproject.toml.tmp
	@echo "✓ pyproject.toml updated successfully"
	@echo "Warning: Minimum Python version is 3.11. Using detected version $(PYTHON_VERSION)"
	@if printf '%s\n' "$(PYTHON_VERSION)" | awk '{ exit ($$1 < 3.11) ? 0 : 1 }'; then \
		echo "ERROR: Python version $(PYTHON_VERSION) detected but minimum required is 3.11"; \
		exit 1; \
	fi

help: ## Show this help message
	@echo "Available commands:"
	@grep -E '^[a-zA-Z_-]+:.*?## .*$$' Makefile | awk 'BEGIN {FS = ":.*?## "} {printf "  %-15s %s\n", $$1, $$2}'

install:
	@$(MAKE) setup-pyproject
	@git config core.editor "vim"
	@poetry config --local virtualenvs.create true
	@poetry config --local virtualenvs.in-project true
	@-$(MAKE) configure-repos
	@poetry lock
	@poetry install --with dev --all-extras
	@$(MAKE) export-reqs
	@poetry run pre-commit install --hook-type pre-commit --hook-type pre-push

export-reqs: ## Export dependencies to requirements.txt
	@echo "Checking for poetry export plugin..."
	@poetry self show poetry-plugin-export >/dev/null 2>&1 || \
		(echo "Installing poetry export plugin..." && poetry self add poetry-plugin-export)
	@echo "Exporting dependencies to requirements.txt..."
	@poetry export --format=requirements.txt --without-hashes | awk -F';' '{print $1}' > $(CURDIR)/requirements.txt
	@echo "Requirements exported to $(CURDIR)/requirements.txt"

hooks: ## Run pre-commit hooks
	@poetry run pre-commit run --all-files --hook-stage commit --hook-stage pre-push

lint:
	@echo "Running ruff linter..."
	ruff check --fix .

lint-check:
	@echo "Running ruff linter (check only)..."
	ruff check --unsafe-fixes .

lint-stats:
	@echo "Running ruff linter statistics..."
	ruff check --statistics .

format:
	@echo "Running ruff formatter..."
	ruff format .

format-check:
	@echo "Running ruff formatter (check only)..."
	ruff format --diff .

secrets:
	#@echo "Running detect-secrets...""
	detect-secrets scan .

update-licensecheck: ## Update licensecheck
	@poetry run licensecheck  --format=simple --file LICENSE-3rd-party.txt

test: ## Execute pytest tests under the tests directory
	@poetry run pytest tests
	@echo "Testing completed."

test-html: ## Execute pytest tests under the tests directory with html report
	@poetry run pytest tests --junitxml=report.xml tests
	@echo "Testing completed."

test-coverage: ## Execute pytest tests under the tests directory with coverage report
	@poetry run pytest \
	    --cov \
	    --cov-report=xml:coverage.xml \
	    --cov-report term  \
		--junitxml=report.xml \
	    --disable-warnings \
	    tests/

	@echo "Coverage reports generated (terminal + coverage.xml + report.xml)."
	@echo "To generate an HTML coverage report locally, you can run:"
	@echo "  poetry run coverage html"

bump-patch: ## Bump patch version, create commit and tag (don't forget to push with --tags)
	@echo "Bumping patch version from $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3)..."
	@poetry run bump2version patch
	@echo "✅ Bumped to $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3) (tag: v$$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3))"
	@echo "Don't forget to push the changes and tags with: git push && git push --tags"

bump-minor: ## Bump minor version, create commit and tag (don't forget to push with --tags)
	@echo "Bumping minor version from $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3)..."
	@poetry run bump2version minor
	@echo "✅ Bumped to $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3) (tag: v$$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3))"
	@echo "Don't forget to push the changes and tags with: git push && git push --tags"

bump-major: ## Bump major version, create commit and tag (don't forget to push with --tags)
	@echo "Bumping major version from $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3)..."
	@poetry run bump2version major
	@echo "✅ Bumped to $$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3) (tag: v$$(grep 'current_version = ' .bumpversion.cfg | cut -d' ' -f3))"
	@echo "Don't forget to push the changes and tags with: git push && git push --tags"

build: ## Build wheel package
	@poetry build
	@echo "Wheel package built in dist/ directory"

configure-repos:
	@echo "Configuring custom PyPI repositories (nv-private and nv-shared)..."
	@if [ -z "$(JFROG_TOKEN)" ]; then \
		echo "Failed: Missing required environment variable JFROG_TOKEN"; \
		echo "Skipping custom repository configuration. Only public PyPI packages will be available."; \
		exit 1; \
	else \
		poetry config repositories.nv-private-pypi "$(NV_PRIVATE_PYPI_URL)" && \
		poetry config repositories.nv-shared-pypi "$(NV_SHARED_PYPI_URL)" && \
		poetry config http-basic.nv-private-pypi "$(USER)" "$(JFROG_TOKEN)" && \
		poetry config http-basic.nv-shared-pypi "$(USER)" "$(JFROG_TOKEN)" && \
		echo "Success: Custom PyPI repositories (nv-private and nv-shared) configured successfully" || \
		(echo "Failed: Error configuring custom repositories" && exit 1); \
	fi

publish: build ## Publish wheel package to Artifactory
	@poetry publish --repository nv-private-pypi
	@echo "Package published to nv-private-pypi Artifactory"

publish-shared: build ## Publish wheel package to Artifactory
	@poetry publish --repository nv-shared-pypi
	@echo "Package published to nv-shared-pypi Artifactory"

clean:  ## Clean Python Related Files And Cache
	@find . -type d -name "__pycache__" -exec rm -rf {} +
	@find . -type d -name "*.egg-info" -exec rm -rf {} +
	@find . -type d -name ".ipynb_checkpoints" -exec rm -rf {} +
	@find . -type d -name ".DS_Store" -exec rm -rf {} +
	@find . -type f -name "*.pyc" -delete
	@find . -type f -name "*.pyo" -delete
	@find . -type f -name "*.pyd" -delete
	@rm -rf .pytest_cache
	@rm -rf .coverage coverage.xml htmlcov/ report.xml
	@rm -rf dist/ build/
	@rm -rf .tox/
	@echo "Cleaned Python related files and cache"

# # Make all targets (except clean) depend on check-python-env
